import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

var pages = [{ id: 'overview', label: 'Обзор' }, { id: 'history', label: 'История', badge: 12 }, { id: 'settings', label: 'Настройки' }];
function App() {
    var a = React.useState('overview');
    var pageContent = { overview: 'В группе 12 объектов. Данные обновлены сегодня.', history: 'Последнее изменение: объект «Грузовик 12» добавлен в группу.', settings: 'Название группы: «Основной парк». Уведомления включены.' };
    function panel(items, state, idBase, content) {
        return items.map(function (it) {
            return <S.DsTabPanel key={it.id} idBase={idBase} id={it.id} active={state === it.id}>
    <div className={'panel'}>
    <p>
    {content[it.id]}
    </p>
    </div>
    </S.DsTabPanel>;
        });
    }
    return <div className="dstabs-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <S.DsTabs idBase={'object-tabs'} items={pages} active={a[0]} onChange={a[1]} aria-label={'Карточка группы'}/>
    {panel(pages, a[0], 'object-tabs', pageContent)}
    </div>
    </div>;
}

const exampleStyles = ".dstabs-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dstabs-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dstabs-example p{margin:0}\n.dstabs-example .panel{padding:16px 0}\n.dstabs-example .panel p{margin:0 0 12px}";

export { App as Example };

