import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

var sections = [{ id: 'objects', label: 'Объекты', icon: 'directions_car' }, { id: 'reports', label: 'Отчёты', icon: 'bar_chart' }, { id: 'alerts', label: 'События', icon: 'notifications', badge: 2 }];
function App() {
    var c = React.useState('objects');
    function header(title, state, stack) {
        return <div className={"demo-stack"}>
    <div className={'header'}>
    <S.DsTabs tone={'onHeader'} stack={stack} items={stack ? sections : sections.map(function (it) { return { id: it.id, label: it.label, badge: it.badge }; })} active={state[0]} onChange={state[1]} aria-label={title}/>
    </div>
    <p>
    {'Открыт раздел: ' + sections.find(function (it) { return it.id === state[0]; }).label + '.'}
    </p>
    </div>;
    }
    return <div className="dstabs-example">
    <style>{exampleStyles}</style>
    {header('Навигация в шапке', c, true)}
    </div>;
}

const exampleStyles = ".dstabs-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dstabs-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dstabs-example p{margin:0}\n.dstabs-example .header{background:var(--ds-surface);color:var(--ds-fg-strong);padding:0 8px;border-radius:var(--ds-radius-md)}";

export { App as Example };

